/**
 * OP.GG MCP client. This is the ONLY module that knows the data comes from
 * OP.GG; the rest of the app must use the neutral types in ./types.ts.
 *
 * Tool names/params: see docs/opgg-tools.json (generated by
 * scripts/list-opgg-tools.ts). Conversion to neutral types arrives in Phase 1.
 */
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StreamableHTTPClientTransport } from "@modelcontextprotocol/sdk/client/streamableHttp.js";
import { DEFAULT_TIMEOUT_MS, DataSourceError, withTimeout } from "./errors";

export const DEFAULT_OPGG_MCP_URL = "https://mcp-api.op.gg/mcp";

export function getOpggUrl(env: Record<string, string | undefined> = process.env): string {
  return env.OPGG_MCP_URL?.trim() || DEFAULT_OPGG_MCP_URL;
}

let clientPromise: Promise<Client> | null = null;

async function connect(): Promise<Client> {
  const client = new Client({ name: "rat-draft", version: "0.1.0" });
  const transport = new StreamableHTTPClientTransport(new URL(getOpggUrl()));
  await withTimeout(client.connect(transport), "opgg");
  return client;
}

/** Reuses one connection across requests; a failed connect is retried next time. */
async function getClient(): Promise<Client> {
  if (!clientPromise) {
    clientPromise = connect().catch((err: unknown) => {
      clientPromise = null;
      throw toDataError(err, "connect");
    });
  }
  return clientPromise;
}

async function resetClient(): Promise<void> {
  const current = clientPromise;
  clientPromise = null;
  if (current) {
    try {
      await (await current).close();
    } catch {
      // connection was already broken
    }
  }
}

function toDataError(err: unknown, what: string): DataSourceError {
  if (err instanceof DataSourceError) return err;
  const message = err instanceof Error ? err.message : String(err);
  const code = /timed? ?out/i.test(message) ? "timeout" : "network";
  return new DataSourceError("opgg", code, `OP.GG ${what} failed: ${message}`, { cause: err });
}

/** Runs an operation on the shared client; on failure reconnects once and retries. */
async function withClient<T>(what: string, op: (client: Client) => Promise<T>): Promise<T> {
  try {
    return await op(await getClient());
  } catch (first) {
    if (first instanceof DataSourceError && first.code !== "network") throw first;
    await resetClient();
    try {
      return await op(await getClient());
    } catch (second) {
      throw toDataError(second, what);
    }
  }
}

export interface OpggToolInfo {
  name: string;
  description?: string;
  inputSchema: unknown;
}

export async function listOpggTools(): Promise<OpggToolInfo[]> {
  return withClient("tools/list", async (client) => {
    const tools: OpggToolInfo[] = [];
    let cursor: string | undefined;
    do {
      const page = await client.listTools(cursor ? { cursor } : undefined, {
        timeout: DEFAULT_TIMEOUT_MS,
      });
      for (const t of page.tools) {
        tools.push({ name: t.name, description: t.description, inputSchema: t.inputSchema });
      }
      cursor = page.nextCursor;
    } while (cursor);
    return tools;
  });
}

/**
 * Calls an OP.GG tool and returns its text content (OP.GG returns the data as
 * text). Throws a DataSourceError on timeout, transport error or tool error.
 */
export async function callOpggTool(name: string, args: Record<string, unknown>): Promise<string> {
  const result = await withClient(name, (client) =>
    client.callTool({ name, arguments: args }, undefined, { timeout: DEFAULT_TIMEOUT_MS }),
  );

  const content = Array.isArray(result.content) ? result.content : [];
  const text = content
    .filter((c): c is { type: "text"; text: string } => c?.type === "text" && typeof c.text === "string")
    .map((c) => c.text)
    .join("\n");

  if (result.isError) {
    const code = /not\s*found|존재하지/i.test(text) ? "not_found" : "bad_response";
    throw new DataSourceError("opgg", code, `OP.GG ${name} error: ${text.slice(0, 300)}`);
  }
  return text;
}

/** Closes the shared connection (used by scripts). */
export async function closeOpgg(): Promise<void> {
  await resetClient();
}
